from diag import *
from sklearn.isotonic import IsotonicRegression
def grp(X): return np.where(X.region=='Eastern','E',np.where(X.region=='Southwest','SW','O'))
def iso_pooled(Xa,ya,Xb):
    m=IsotonicRegression(out_of_bounds='clip').fit(np.log10(Xa.proposed_penalty_usd),ya); return m.predict(np.log10(Xb.proposed_penalty_usd))
def iso_region(Xa,ya,Xb):
    ga,gb=grp(Xa),grp(Xb); out=np.zeros(len(Xb))
    for g in ['E','SW','O']:
        m=IsotonicRegression(out_of_bounds='clip').fit(np.log10(Xa.proposed_penalty_usd[ga==g]),ya[ga==g]); out[gb==g]=m.predict(np.log10(Xb.proposed_penalty_usd[gb==g]))
    return out
def iso_additive(Xa,ya,Xb):
    # pooled isotonic curve times region odds offsets estimated on training residuals
    base=iso_pooled(Xa,ya,Xa); ga,gb=grp(Xa),grp(Xb); pb=iso_pooled(Xa,ya,Xb); out=pb.copy()
    for g in ['E','SW','O']:
        ratio=(ya[ga==g].sum()+5*1.0)/(base[ga==g].sum()+5*1.0); out[gb==g]=pb[gb==g]*ratio
