from cv import *
from sklearn.linear_model import LogisticRegression
EV=pd.read_csv(ROOT/'release/extract/public/eval.csv'); YE=EV.penalty_reduced.to_numpy()
def feats(d,region=True):
    Z=pd.DataFrame({'lp':np.log10(d.proposed_penalty_usd.to_numpy())})
    if region:
        for r in ['Central','Eastern','Southern','Southwest']: Z[r]=(d.region.to_numpy()==r).astype(float)
